### 2. Implement Secure Secrets Hierarchy
```javascript
// config.js - improved version
require('dotenv').config();

// Never commit production secrets to git
const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Database
  databaseUrl: process.env.DATABASE_URL || 'postgresql://localhost:5432/devdb',

  // API Keys
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,

  // JWT
  jwtSecret: process.env.JWT_SECRET || generateDevSecret(),

  // AWS
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1'
  }
};

function generateDevSecret() {
  if (process.env.NODE_ENV === 'production') {
    console.error('JWT_SECRET missing in production!');
    process.exit(1);
  }
  return 'dev-secret-key-change-in-production'; // Only for development
}

// Validate required production secrets
if (config.nodeEnv === 'production') {
  const required = ['JWT_SECRET', 'DATABASE_URL'];
  required.forEach(secret => {
    if (!process.env[secret]) {
      console.error(`Missing required secret: ${secret} in production`);
      process.exit(1);
    }
  });
}

module.exports = config;
```

### 3. Git Protection for Secrets
Add to `.gitignore`:
```
# Environment variables
.env
.env.local
.env.production
.env.staging

# Secrets
secrets.json
*.pem
*.key
```

