For production environments, use proper secrets managers:

```javascript
// In production, prefer cloud secrets managers
async function getSecretFromAWS() {
  const AWS = require('aws-sdk');
  const client = new AWS.SecretsManager();

  try {
    const data = await client.getSecretValue({
      SecretId: 'production/app-secrets'
    }).promise();

    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw error;
  }
}

// Dynamically load based on environment
const secrets = process.env.SECRETS_MANAGER === 'aws' 
  ? await getSecretFromAWS() 
  : require('./config'); // fall back to env vars
```

### 5. Secrets Monitoring & Rotation
```javascript
// Security check middleware - warn about weak secrets
function checkSecretsSecurity() {
  const weakPatterns = [
    /change-this|default|password|secret-key|12345/i,
    /^sk_live_[a-zA-Z0-9]{8}$/ // Short live keys
  ];

  Object.keys(process.env).forEach(key => {
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('PASSWORD')) {
      const value = process.env[key];
      if (value && weakPatterns.some(pattern => pattern.test(value))) {
        console.warn(`⚠️  Weak secret detected in ${key}: ${value.substring(0, 8)}...`);
        console.warn('Rotate this secret immediately in production!');
      }
    }
  });
}

// Run security check
if (process.env.NODE_ENV !== 'test') {
  checkSecretsSecurity();
}
```

