**Option B: Secrets Manager Integration**

```javascript
// secrets.js - Example with AWS Secrets Manager
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager();
  }

  async getSecret(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      return JSON.parse(data.SecretString);
    } catch (error) {
      console.error('Failed to retrieve secret:', error);
      throw error;
    }
  }

  // Cache secrets with rotation
  async getCachedSecret(secretName, ttl = 300000) { // 5 minute default
    const now = Date.now();

    if (!this.cache || !this.cache[secretName] || 
        (now - this.cache[secretName].timestamp) > ttl) {

      if (!this.cache) this.cache = {};
      this.cache[secretName] = {
        data: await this.getSecret(secretName),
        timestamp: now
      };
    }

    return this.cache[secretName].data;
  }
}

module.exports = SecretsManager;
```

